type Analytics = { pageViews: number; visitors: number }
type Notification = { id: number; message: string }
type Settings = { theme: string; emailAlerts: boolean }

// Server-side fetch requires absolute URLs, so resolve the /api paths against
// the app's own origin.
const BASE_URL =
  process.env.NEXT_PUBLIC_BASE_URL ??
  (process.env.VERCEL_URL
    ? `https://${process.env.VERCEL_URL}`
    : 'http://localhost:3000')

async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${BASE_URL}/api/analytics`).then((r) => r.json()),
      fetch(`${BASE_URL}/api/notifications`).then((r) => r.json()),
      fetch(`${BASE_URL}/api/settings`).then((r) => r.json()),
    ])

    return { analytics, notifications, settings } as {
      analytics: Analytics
      notifications: Notification[]
      settings: Settings
    }
  } catch {
    // Return mock data for build time
    return {
      analytics: { pageViews: 0, visitors: 0 },
      notifications: [] as Notification[],
      settings: { theme: 'light', emailAlerts: false },
    }
  }
}

